function Fail([string]$Message) { $script:failures.Add($Message) }
function Value { param([AllowNull()]$Object,[string]$Name); if($null-eq$Object){return $null};$property=$Object.PSObject.Properties[$Name];if($null-eq$property){return $null};return $property.Value }
function Has { param([AllowNull()]$Object,[string]$Name); return $null-ne$Object-and$null-ne$Object.PSObject.Properties[$Name] }
function Need([bool]$Condition,[string]$Message){if(-not$Condition){Fail $Message}}
function Same { param([AllowNull()]$Actual,[AllowNull()]$Expected,[string]$Message);if($null-eq$Actual-or$null-eq$Expected-or-not[object]::Equals($Actual,$Expected)){Fail "$Message Expected '$Expected', observed '$Actual'."} }
function Markers { param([AllowNull()]$Object,[string]$Context);Same (Value $Object 'validation_mode') 'automated' "$Context validation_mode differs.";Same (Value $Object 'owner_manual_ux_smoke') 'waived' "$Context owner_manual_ux_smoke differs.";$manual=Value $Object 'manual_evidence_claimed';Need ($manual-is[bool]-and-not$manual) "$Context manual_evidence_claimed must be boolean false.";Same (Value $Object 'historical_manual_gate') 'not_closed_superseded_as_release_blocker' "$Context historical_manual_gate differs." }
function CaptureMarker { param([AllowNull()]$Object,[string]$Context);Markers $Object $Context;Same (Value $Object 'automated_capture_status') 'captured' "$Context automated_capture_status differs." }
function Json([string]$Path,[string]$Context){try{return Get-Content -LiteralPath $Path -Raw -Encoding UTF8|ConvertFrom-Json}catch{Fail "$Context is missing or invalid JSON: $($_.Exception.Message) ";return $null}}
function FullPath([AllowNull()][string]$Path){return -not [string]::IsNullOrWhiteSpace($Path) -and [IO.Path]::IsPathRooted($Path)}
function SamePath([AllowNull()][string]$First,[AllowNull()][string]$Second){if(-not (FullPath $First) -or -not (FullPath $Second)){return $false};return [string]::Equals([IO.Path]::GetFullPath($First).TrimEnd('\','/'),[IO.Path]::GetFullPath($Second).TrimEnd('\','/'),[StringComparison]::OrdinalIgnoreCase)}
function InRoot([AllowNull()][string]$Path,[string]$Root){if(-not (FullPath $Path)){return $false};$full=[IO.Path]::GetFullPath($Path).TrimEnd('\','/');$base=[IO.Path]::GetFullPath($Root).TrimEnd('\','/');return [string]::Equals($full,$base,[StringComparison]::OrdinalIgnoreCase) -or $full.StartsWith($base+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)}
function RelativePath { param([AllowNull()][string]$Path,[string]$Root,[string]$Context);if([string]::IsNullOrWhiteSpace($Path)-or[IO.Path]::IsPathRooted($Path)){Fail "$Context must be run-relative.";return $null};try{$full=[IO.Path]::GetFullPath((Join-Path $Root $Path));if(-not (InRoot $full $Root)){Fail "$Context escapes the run root.";return $null};return $full}catch{Fail "$Context is invalid.";return $null} }
function Hash([string]$Path,[string]$Context){if(-not (Test-Path -LiteralPath $Path -PathType Leaf)){Fail "$Context is missing: '$Path'.";return $null};try{$stream=[IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$sha=[Security.Cryptography.SHA256]::Create();try{return (($sha.ComputeHash($stream)|ForEach-Object{$_.ToString('x2')})-join '')}finally{$sha.Dispose()}}finally{$stream.Dispose()}}catch{Fail "$Context cannot be hashed: $($_.Exception.Message) ";return $null}}
function Hex64([AllowNull()]$Text){return $null -ne $Text -and [string]$Text -cmatch '^[0-9a-f]{64}$'}
function ZeroSafety { param([AllowNull()]$Safety,[object[]]$Names,[string]$Context);foreach($name in $Names){$observed=Value $Safety([string]$name);Need ($observed-is[int]-or$observed-is[long]) "$Context $name must be an integer.";if($observed-is[int]-or$observed-is[long]){Same ([long]$observed) 0L "$Context $name is non-zero."}} }
function FileIdentity { param([AllowNull()]$Object,[string]$Context,[string]$RunId,[string]$Head,[int]$EvidencePid,[string]$Hwnd,[string]$ExeHash,[string]$DllHash,[string]$ScenarioId);Markers $Object $Context;Same (Value $Object 'run_id') $RunId "$Context run id differs.";Same (Value $Object 'source_head') $Head "$Context source HEAD differs.";Same ([int](Value $Object 'pid'))$EvidencePid "$Context PID differs.";Same ([string](Value $Object 'hwnd')) $Hwnd "$Context HWND differs.";Same ([string](Value $Object 'executable_sha256') ) $ExeHash "$Context executable hash differs.";Same ([string](Value $Object 'asset_module_sha256')) $DllHash "$Context module hash differs.";Same ([string](Value $Object 'scenario_id')) $ScenarioId "$Context scenario differs." }
function ProcessResult { param([AllowNull()]$Result,[string]$Context,[string]$Root,[string[]]$RequiredArguments)
    Same ([int](Value $Result 'exit_code')) 0 "$Context exit code differs.";$file=[string](Value $Result 'file');Need (FullPath $file) "$Context executable path is not absolute.";Need (Test-Path -LiteralPath $file -PathType Leaf) "$Context executable is missing.";$arguments=@((Value $Result 'arguments'));foreach($required in $RequiredArguments){Need ($arguments-ccontains$required) "$Context arguments lack '$required'."}
