    foreach($field in @('stdout','stderr')){$path=[string](Value $Result $field);Need (InRoot $path $Root) "$Context $field is outside run root.";$declared=[string](Value $Result ($field+'_sha256'));Need (Hex64 $declared) "$Context $field hash is invalid.";if(Test-Path -LiteralPath $path -PathType Leaf){Same (Hash $path "$Context $field") $declared "$Context $field hash differs."}else{Fail "$Context $field is missing."}}
}
function Read-And-ValidateHashChain { param([string]$Path,[string]$PreviousName,[string]$HashName,[string]$Context)
    $records=[Collections.Generic.List[object]]::new();$previous='0'*64;$lineNumber=0
    if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){Fail "$Context is missing.";return $records}
    foreach($line in Get-Content -LiteralPath $Path -Encoding UTF8){$lineNumber++;if([string]::IsNullOrWhiteSpace($line)){Fail "$Context line $lineNumber is blank.";continue};try{$record=$line|ConvertFrom-Json}catch{Fail "$Context line $lineNumber is invalid JSON.";continue};Markers $record "$Context line $lineNumber";Same (Value $record $PreviousName) $previous "$Context line $lineNumber previous hash differs.";Same (Value $record 'previous_record_sha256') $previous "$Context line $lineNumber generic previous hash differs.";$declared=[string](Value $record $HashName);Same (Value $record 'record_sha256') $declared "$Context line $lineNumber generic record hash differs.";Need (Hex64 $declared) "$Context line $lineNumber record hash is invalid.";$escaped=[regex]::Escape($declared);$suffix=',"'+$HashName+'":"'+$escaped+'","record_sha256":"'+$escaped+'"}$';$canonical=[regex]::Replace($line,$suffix,'}');Need ($canonical.Length-lt$line.Length) "$Context line $lineNumber hash fields are not the final ordered fields.";$bytes=[Text.Encoding]::UTF8.GetBytes($canonical);$sha=[Security.Cryptography.SHA256]::Create();try{$actual=(($sha.ComputeHash($bytes)|ForEach-Object{$_.ToString('x2')})-join'')}finally{$sha.Dispose()};Same $actual $declared "$Context line $lineNumber record hash differs.";$previous=$declared;$records.Add($record)}
    return $records
}
function HashBytes([byte[]]$Bytes){$sha=[Security.Cryptography.SHA256]::Create();try{return(($sha.ComputeHash($Bytes)|ForEach-Object{$_.ToString('x2')})-join'')}finally{$sha.Dispose()}}
function Convert-HexColor { param([string]$Value);$hex=$Value.Trim().TrimStart('#');if($hex.Length-eq 8){$hex=$hex.Substring(2)};if($hex.Length-ne 6){throw "Unsupported color '$Value'."};return @([Convert]::ToInt32($hex.Substring(0,2),16),[Convert]::ToInt32($hex.Substring(2,2),16),[Convert]::ToInt32($hex.Substring(4,2),16)) }
function Get-RelativeLuminance { param([string]$Color);$channels=Convert-HexColor $Color;$linear=@($channels|ForEach-Object{$channel=$_/255;if($channel-le 0.04045){$channel/12.92}else{[Math]::Pow(($channel+0.055)/1.055,2.4)}});return 0.2126*$linear[0]+0.7152*$linear[1]+0.0722*$linear[2] }
function Get-LuminanceContrast { param([double]$First,[double]$Second);$high=[Math]::Max($First,$Second);$low=[Math]::Min($First,$Second);return($high+0.05)/($low+0.05) }
function Get-ContrastRatio { param([string]$Foreground,[string]$Background);return Get-LuminanceContrast (Get-RelativeLuminance $Foreground) (Get-RelativeLuminance $Background) }
function Invoke-GitText { param([string]$RepositoryRoot,[string[]]$Arguments,[string]$Context);$result=& git.exe -C $RepositoryRoot @Arguments 2>&1;$exit=$LASTEXITCODE;if($exit-ne 0){Fail "$Context failed (git exit $exit): $($result-join' ')";return $null};return([string]($result-join"`n")).Trim() }
function Get-GitBlobBytes { param([string]$RepositoryRoot,[string]$Head,[string]$Path)
    $start=[Diagnostics.ProcessStartInfo]::new();$start.FileName='git.exe';$start.Arguments="-C `"$RepositoryRoot`" cat-file blob `"$Head`:$Path`"";$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
    try{$process=[Diagnostics.Process]::Start($start);$memory=[IO.MemoryStream]::new();try{$process.StandardOutput.BaseStream.CopyTo($memory);$error=$process.StandardError.ReadToEnd();$process.WaitForExit();if($process.ExitCode-ne 0){Fail "git cat-file failed for '$Path': $error";return $null};return $memory.ToArray()}finally{$memory.Dispose();$process.Dispose()}}catch{Fail "git cat-file failed for '$Path': $($_.Exception.Message)";return $null}
}
function Test-RepositoryIdentity { param([string]$RepositoryRoot,[string]$Head,[string]$Branch,[string]$RunRoot,[string]$ExePath,[string]$DllPath)
    Need (FullPath $RepositoryRoot) 'repository_root must be absolute.';Need (Test-Path -LiteralPath $RepositoryRoot -PathType Container) 'repository_root does not exist.';if(-not(Test-Path -LiteralPath $RepositoryRoot -PathType Container)){return}
