    Need (InRoot $RunRoot $RepositoryRoot) 'Run root is outside repository_root.';Need (InRoot $ExePath $RepositoryRoot) 'Executable is outside repository_root.';Need (InRoot $DllPath $RepositoryRoot) 'Asset module is outside repository_root.'
    $expectedBin=Join-Path $RepositoryRoot 'src\RAWSelectionAssistant\bin';Need (InRoot $ExePath $expectedBin) 'Executable is outside the expected repository build output.';Need (InRoot $DllPath $expectedBin) 'Asset module is outside the expected repository build output.'
}
